package com.quincaisoft.purchasing.infrastructure;import jakarta.persistence.*;import java.util.*;import java.time.*;import java.io.Serializable;
@Entity @Table(name="payable_balance")@IdClass(PayableBalance.Key.class)public class PayableBalance{@Id @Column(name="tenant_id")public UUID tenantId;@Id @Column(name="company_id")public UUID companyId;@Id public UUID id;@Column(name="branch_id")public UUID branchId;@Column(name="supplier_id") public UUID supplierId;@Column(name="original_xaf") public long originalXaf;@Column(name="paid_xaf") public long paidXaf;@Version public long version;public record Key(UUID tenantId,UUID companyId,UUID id)implements Serializable{}}